  const body = sec(fill(SITE.introH2, ctx), ps(pickN(forProd(C.intro, ctx._p), seed + ':intro', 3), ctx, seed) + ps(C.productNote[prod.key].slice(0, 2), ctx, seed + ':pn'))
    + C.sections.map(s => angleSection(s, ctx, seed)).join('')
    + sec(fill(T.regionH2, { ...ctx, '지역': '전국' }), ps(pickN(forProd(C.regionDeep, ctx._p), seed + ':rd', 4), { ...ctx, '지역': '전국' }, seed + ':rd'))
    + sec(fill(SITE.casesH2, ctx), cards(pickN(forProd(C.cases, ctx._p), seed + ':case', 4).map((c, i) => ({ t: fill(c.t, ctx), d: para(c.d, ctx, seed + ':cs' + i) }))))
