  const fq = faqBlock(pickN(D.faq, seed + ':bfaq', 3).concat(pickN(forProd(C.faq, ctx._p), seed + ':faq', 2)), ctx, seed, `${b.ko} ${prod.ko} 자주 묻는 질문`);
  return page({ title: fill(SITE.titles.biz, ctx), desc: clip(fill(SITE.descs.biz, ctx) + ' ' + para(C.biz[b.slug][0], ctx, seed), 70, 150), path, prod: prod.key, active: prod.key, top: hero({ crumb: cr.html, h1, hook: fill(pick1(C.hook, seed + ':hook'), ctx) }), body: body + fq.html + ctaSec(fill(pick1(C.cta.h2, seed + ':cta'), ctx), para(pick1(C.cta.p, seed + ':ctap'), ctx, seed + ':ctap')), ld: [cr.ld, fq.ld] });
